update pages set contenu = '{"sections":[{"type":"heros","h1":"Automatisme industriel","mecanisme":"Un automaticien branche son ordinateur, lit les registres de l''automate et teste chaque hypothèse au lieu de la deviner. SIEMENS, Schneider, et la reprise du code écrit par quelqu''un d''autre.","cta":"Demander une intervention","telephone":"04 78 33 72 05","phraseDelai":"Rappel dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7 prend le relais la nuit et le week-end."},{"type":"chiffres","chiffres":[{"valeur":"10 %","libelle":"des candidats retenus, après entretien technique ET comportemental"},{"valeur":"+ 100","libelle":"collaborateurs, depuis 4 agences, Lyon (siège), Montréal, Dubaï et Madrid"},{"valeur":"24/24 et 7/7","libelle":"astreinte, pour les sites couverts"}]},{"type":"probleme","punchline":"Un automate en défaut, et toute la chaîne s''arrête. Personne sur place ne sait lire le programme, alors l''arrêt dure des heures.","puces":[{"accroche":"La sauvegarde est introuvable.","texte":"La machine repart de zéro et plus personne n''a la dernière version du code. C''est la panne la plus chère du parc."},{"accroche":"Un bon automaticien ne se recrute plus.","texte":"Vos deux derniers recrutements ont pris des mois, et vos propres équipes sont déjà chargées."},{"accroche":"Quelqu''un est venu modifier le code sans le tracer.","texte":"Le fonctionnement devient imprévisible et le défaut fantôme revient chaque semaine."},{"accroche":"L''automate n''est plus fabriqué.","texte":"Pièces introuvables, gamme arrêtée, et la migration est repoussée d''année en année jusqu''à la casse."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Un diagnostic qui va à la cause","texte":"lecture des défauts de l''automate, contrôle des entrées et sorties, analyse du code, environnement électrique."},"benefice":"Vous savez pourquoi la ligne s''est arrêtée, pas seulement quelle carte a été changée."},{"prestation":{"accroche":"Vos automatismes sauvegardés et datés","texte":"automates, variateurs, IHM, chaque version archivée."},"benefice":"Le jour où une carte lâche, on recharge au lieu de tout réécrire."},{"prestation":{"accroche":"La reprise d''un code écrit par un autre prestataire","texte":"audit de l''existant, documentation, puis modification propre."},"benefice":"Vous reprenez la main sur votre installation, avec une documentation exploitable par vos équipes."},{"prestation":{"accroche":"L''obsolescence traitée","texte":"migration vers une gamme actuelle, étude et conception du projet comprises."},"benefice":"La décision se prend avec les coûts sous les yeux, avant la panne qui l''impose."},{"prestation":{"accroche":"L''automatisation industrielle de l''existant améliorée","texte":"cycles raccourcis, défauts mieux tracés, alarmes utiles, nouvelle recette intégrée."},"benefice":"La même machine produit plus, avec moins de micro-arrêts et moins de rebuts."},{"prestation":{"accroche":"Les armoires contrôlées en préventif","texte":"dépoussiérage, serrages, tensions, batteries de sauvegarde, températures."},"benefice":"Les gestes simples qui évitent la grande panne, faits avant qu''elle n''arrive."},{"prestation":{"accroche":"Une expertise alignée sur votre parc","texte":"automaticiens SIEMENS et Schneider, avec les variateurs, l''IHM, la supervision et les réseaux de terrain associés."},"benefice":"Chaque marque a son logiciel et ses pièges : le bon spécialiste arrive, pas un généraliste."}],"prose":[{"texte":"Un besoin durable se couvre par la [sous-traitance maintenance](/offres/residence/), un automaticien intégré à votre équipe pour la durée du projet. Une ligne figée maintenant se traite par le [dépannage industriel](/offres/depannage-industriel/)."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez la situation","texte":"marque d''automate, message ou code défaut, moment du cycle, ce qui a été modifié récemment. Quatre champs, ou un appel au 04 78 33 72 05."},{"titre":"Un technicien vous rappelle dans l''heure","texte":"la panne est qualifiée à distance. Vous savez rapidement si nous avons l''automaticien, et lequel."},{"titre":"Brancher et lire","texte":"l''automaticien connecte son ordinateur et lit les registres de l''automate avant de toucher quoi que ce soit."},{"titre":"Isoler le défaut","texte":"entrées, sorties, code, environnement électrique. Chaque hypothèse se teste, elle ne se devine pas."},{"titre":"Réparer, puis prouver","texte":"remplacement du composant ou rechargement de la sauvegarde, remise en service, essais devant vos opérateurs."},{"titre":"Vous recevez un rapport et vos livrables","texte":"cause expliquée en langage clair, code documenté, sauvegardes datées remises chez vous."}]},{"type":"garanties","puces":[{"accroche":"Le rappel dans l''heure, du lundi au vendredi de 8h00 à 18h30.","texte":"L''astreinte 24/24 et 7/7 couvre la nuit et le week-end sur les sites concernés."},{"accroche":"Vos programmes, vos recettes et vos sauvegardes restent chez vous.","texte":"C''est une condition non négociable de notre métier, écrite dans nos engagements de confidentialité."},{"accroche":"Un automaticien évalué en entretien technique et comportemental","texte":", 10 % des candidats retenus, habilitations électriques à jour pour intervenir en armoire, consignation comprise."}]},{"type":"cta","question":"Besoin d''un automaticien capable de lire votre programme aujourd''hui ?","bouton":"Demander une intervention","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Démarrage d''une ligne de production neuve, près de Lyon","texte":"un automaticien spécialisé SIEMENS dédié à temps plein, fiabilisation des installations neuves et suivi continu sur toute la phase de mise en route, T2 et T3 2025","lienLibelle":"Étude de cas MERSEN : nouvelles lignes","lienHref":"/preuves/mersen/"},{"titre":"Renfort continu sur des lignes automatisées, agroalimentaire","texte":"deux techniciens intégrés en 3x8, maîtrise des automates Schneider et des environnements automatisés du site","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"},{"titre":"Maintenance des équipements critiques d''un équipementier automobile","texte":"techniciens intégrés au quotidien sur systèmes automatisés, lignes de production et convoyeurs, depuis 2025","lienLibelle":"Étude de cas JTEKT : maintenance des installations","lienHref":"/preuves/jtekt/"},{"titre":"Contrôle de chantier sur des projets d''automatisation logistique","texte":"plusieurs intervenants intégrés aux équipes, aéroports, logistique et industrie, 2025 à 2026","lienLibelle":"Étude de cas ALSTEF Group : collaboration","lienHref":"/preuves/alstef-group/"},{"titre":"Maintien opérationnel de convoyeurs, trieurs et systèmes de packaging automatisés, logistique et transport","texte":"deux techniciens en poste, surveillance continue des équipements critiques","lienLibelle":"Étude de cas GLS : maintenance curative","lienHref":"/preuves/gls-maintenance-curative/"}]},{"type":"objections","questions":[{"question":"Combien coûte une intervention en automatisme ?","reponse":"Le chiffrage dépend du défaut, de la machine et de l''urgence, et se fait sur devis. Pour une panne ou une modification sur une installation en service, un automaticien expérimenté règle la question sans mobiliser un groupe d''ingénierie complet."},{"question":"Pouvez-vous reprendre un code écrit par un autre prestataire ?","reponse":"Oui, c''est le cas le plus fréquent. Nous auditons l''existant, nous le sauvegardons, nous le documentons, puis nous le modifions proprement. Vous récupérez la main sur votre installation."},{"question":"Qui répond de la sécurité et de la confidentialité ?","reponse":"Habilitations électriques à jour, consignation, plan de prévention signé, respect de vos conditions d''accès. Vos process, vos recettes et vos sauvegardes ne sortent pas de chez vous."},{"question":"Qui intervient sur nos automates ?","reponse":"Des automaticiens salariés de Migen, évalués en entretien technique et comportemental, 10 % des candidats retenus. Nos automaticiens travaillent sur SIEMENS et Schneider, et beaucoup viennent de l''électrotechnique et du terrain."},{"question":"Êtes-vous intégrateur ou mainteneur ?","reponse":"Mainteneur. L''ingénierie conçoit, l''intégrateur installe, nous faisons durer l''existant, nous le réparons et nous le faisons évoluer année après année. Nous travaillons en lien avec votre intégrateur quand votre projet l''exige."},{"question":"Couvrez-vous notre région, et les installations anciennes ?","reponse":"Oui aux deux. 4 agences, Lyon (siège), Montréal, Dubaï et Madrid, et des hubs de techniciens dans les grandes villes de France. Nous maintenons l''existant tant que c''est raisonnable, et nous chiffrons la migration en parallèle."}]},{"type":"ctaFinal","question":"Besoin que quelqu''un sache enfin où se trouve la dernière version de votre programme ?","bouton":"Demander une intervention"}]}'::jsonb where path = '/expertises/automatisme/';
